import {FISH,HABITATS,initialFishing,stepFishing,catchAction} from './model.js';import {FISHING_SPOTS} from './layout.js';import {MAX_FISH_CATCHES} from '../state/fishing.js';import {createFishingView} from './view.js';
export const FISHING_BODY=`<div class="fishing-heading"><strong data-fishing-title></strong><button data-fishing-close aria-label="낚시 그만하기">나가기 ×</button></div><div class="fishing-court" data-fishing-court tabindex="0" role="img" aria-label="낚싯대를 든 도름이와 물 위의 찌"></div><section class="fishing-panel" aria-label="낚시 조작"><p data-fishing-status role="status" aria-live="polite"></p><div class="fishing-meters"><label data-fishing-meter-label>던질 힘 <progress data-fishing-power max="1" value="0"></progress></label><label data-fishing-distance-label>남은 거리 <progress data-fishing-distance max="1" value="0"></progress></label></div><div class="fishing-actions"><button data-fishing-main class="fishing-main">누르고 있다 놓아 던지기</button><button data-fishing-pause aria-label="낚시 잠깐 쉬기">쉬기</button></div><p class="fishing-help" data-fishing-help>길게 눌러 힘을 모으고 놓으면 던져요 · Space도 같아요</p></section>`;
const escapeReasons={early:'아직 물지 않았어요. 찌가 푹 잠길 때 챔질해요',missed:'물고기가 지나갔어요. 다음 입질을 기다려 볼까요?',tension:'줄을 너무 세게 당겼어요. 빨개지기 전에 손을 놓아요',slack:'줄이 느슨해졌어요. 조금씩 쉬며 감아 봐요'};
export function createFishingController({ui,getView,getActors,getRoom,getProgress,transact,canSave=()=>true,onActive=()=>{},stage,reduced=false,doc=globalThis.document,win=globalThis.window,createView=createFishingView,random=Math.random,now=()=>new Date().toISOString()}){
 let live=null;const listen=(s,n,t,f)=>{n?.addEventListener(t,f);s.listeners.push([n,t,f]);};
 function clear(s){s.hold=false;s.pointer=null;s.key=null;}
 function render(s){if(live!==s)return;const a=s.state,$=selector=>s.root.querySelector(selector),main=$('[data-fishing-main]'),phase=a.phase,done=phase==='caught';
  const descriptions={ready:'물 위에 동그란 찌를 띄워 볼까요?',charging:'힘을 모으는 중 · 손을 놓으면 던져요',casting:'휘익, 찰랑!',waiting:'찌를 바라봐요 · 살짝 흔들려도 기다려요',bite:'퐁! 지금 한 번 눌러요!',reeling:'누르면 감기 · 빨개지기 전에 놓아 쉬기',landing:'물 밖으로 살며시 올려요',caught:s.saved?`${FISH[a.fishId].label} 한 마리 · 재료가방에 보관했어요`:'저장하지 못했어요 · 다시 저장하거나 나갈 수 있어요',escaped:escapeReasons[a.reason]??'다시 던져 볼까요?'};
  const text=!canSave()?'저장 연결을 확인해 주세요 · 이번 물고기는 아직 보관하지 않았어요':s.paused?'잠시 쉬는 중 · 계속하기를 누르면 이어져요':descriptions[phase];if(s.status!==text){$('[data-fishing-status]').textContent=text;s.status=text;}
  main.textContent=s.paused?'계속하기':phase==='ready'?'누르고 있다 놓아 던지기':phase==='charging'?'놓으면 던져요':phase==='bite'?'지금 챔질!':phase==='reeling'?(s.hold?'감는 중 · 놓으면 쉬어요':'꾹 눌러 감기'):done&&!s.saved?'저장 다시 시도':done||phase==='escaped'?'한 번 더 던지기':'찌를 기다려요';
  main.disabled=!canSave()||!s.paused&&['casting','waiting','landing'].includes(phase);main.setAttribute('aria-pressed',String(s.hold));$('[data-fishing-pause]').disabled=s.paused;const tension=phase==='reeling';$('[data-fishing-meter-label]').firstChild&&($('[data-fishing-meter-label]').firstChild.textContent=tension?'줄의 당김 ':'던질 힘 ');$('[data-fishing-power]').value=tension?a.tension:a.power;$('[data-fishing-power]').setAttribute('aria-label',tension?'줄의 당김. 빨개지면 손을 놓아요':'던질 힘');s.root.style.setProperty('--fishing-tension',a.tension>.72?'#d47d66':'#719d91');$('[data-fishing-distance]').value=a.progress;$('[data-fishing-distance-label]').hidden=!['reeling','landing','caught'].includes(phase);$('[data-fishing-help]').textContent=tension?'감기와 쉬기를 번갈아 해요 · 당김 막대가 빨개지면 놓아요':done?'잡은 물고기는 재료가방에서 다시 볼 수 있어요':phase==='bite'?'찌가 잠긴 지금! 버튼이나 Space를 한 번 눌러요':'누르고 놓아 던지기 → 찌가 잠기면 누르기 → 쉬어 가며 감기';s.view.update(a,s.hold);
 }
 function close(token=live){if(!live||token!==live)return;const s=live;live=null;clear(s);for(const[n,t,f]of s.listeners)n?.removeEventListener(t,f);s.view.dispose();s.root.remove();stage.classList.remove('fishing-open');doc.body?.classList.remove('fishing-open');onActive(false);if(!doc.hidden)doc.querySelector?.('#scene')?.focus?.({preventScroll:true});}
 function pause(s=live){if(!s||live!==s)return;clear(s);if(s.state.phase==='charging')s.state={...s.state,phase:'ready',elapsed:0,power:0};s.paused=true;render(s);}
 function saveCatch(s){if(s.saved||live!==s||!canSave())return;const action=catchAction(s.state);if(!action)return;s.attempted=true;s.caughtAt??=now();s.saved=transact({...action,caughtAt:s.caughtAt});render(s);}
 function press(s){if(live!==s||s.paused||doc.hidden||!canSave())return;const p=s.state.phase;if(p==='reeling')s.hold=true;else if(['ready','bite'].includes(p)){s.state=stepFishing(s.state,{type:'PRESS'});s.hold=s.state.phase==='reeling';}render(s);}
 function release(s){if(live!==s)return;s.hold=false;if(!s.paused)s.state=stepFishing(s.state,{type:'RELEASE'});render(s);}
 function click(s){if(live!==s||doc.hidden||!canSave())return;if(s.paused){clear(s);s.paused=false;render(s);return;}if(s.state.phase==='caught'&&!s.saved){saveCatch(s);return;}if(['caught','escaped'].includes(s.state.phase)){if(getProgress().fishing.total>=MAX_FISH_CATCHES){ui.toast('낚시 기록이 가득 찼어요. 남은 물고기는 재료가방에서 볼 수 있어요');return;}clear(s);s.state=initialFishing(s.state.habitat,{seed:random(),expectedTotal:getProgress().fishing.total,spotId:s.spotKey});s.saved=false;s.attempted=false;s.caughtAt=null;render(s);return;}if(s.state.phase==='charging')release(s);else if(s.state.phase==='reeling'){s.hold=!s.hold;render(s);}else press(s);}
 function open(spotKey){if(live)return false;const spot=FISHING_SPOTS[spotKey],habitat=spot?.habitat;if(!spot||spot.roomId!==getRoom()||!getView()?.root)return false;if(!canSave()){ui.toast('이 탭은 둘러보기 모드예요. 저장 안내를 확인해 주세요');return false;}if(getProgress().fishing.total>=MAX_FISH_CATCHES){ui.toast('낚시 기록이 가득 찼어요. 남은 물고기는 재료가방에서 볼 수 있어요');return false;}
  const root=doc.createElement('div');root.className='fishing-overlay';root.innerHTML=FISHING_BODY;root.setAttribute('role','group');root.setAttribute('aria-label',HABITATS[habitat].label);stage.appendChild(root);let s;
  try{const view=createView({...getActors(),zoneRoot:getView().root,spot,reduced});s={root,view,spotKey,caughtAt:null,listeners:[],state:initialFishing(habitat,{seed:random(),expectedTotal:getProgress().fishing.total,spotId:spotKey}),saved:false,attempted:false,paused:false,hold:false,pointer:null,key:null,fit:null};live=s;stage.classList.add('fishing-open');doc.body?.classList.add('fishing-open');onActive(true);const $=selector=>root.querySelector(selector),button=$('[data-fishing-main]');$('[data-fishing-title]').textContent=spot.shortLabel+' 낚시';
   listen(s,$('[data-fishing-close]'),'click',()=>close(s));listen(s,$('[data-fishing-pause]'),'click',()=>pause(s));
   listen(s,button,'pointerdown',e=>{if(live!==s||e.button!==0||e.isPrimary===false||s.pointer!==null||s.key||button.disabled||s.paused||['caught','escaped'].includes(s.state.phase))return;e.preventDefault();s.pointer=e.pointerId;button.setPointerCapture?.(e.pointerId);press(s);});
   for(const type of ['pointerup','pointercancel','lostpointercapture'])listen(s,button,type,e=>{if(live!==s||s.pointer!==e.pointerId)return;s.pointer=null;if(type==='pointerup')release(s);else pause(s);});
   listen(s,button,'click',e=>{if(live!==s)return;e.preventDefault();if(s.paused||['caught','escaped'].includes(s.state.phase)||e.detail===0&&!s.key&&s.pointer===null)click(s);});
   listen(s,doc,'keydown',e=>{if(live!==s||e.ctrlKey||e.altKey||e.metaKey)return;if(e.code==='Escape'){e.preventDefault();close(s);return;}if(!['Space','Enter'].includes(e.code)||e.code==='Enter'&&e.target!==button||e.target?.tagName==='BUTTON'&&e.target!==button)return;e.preventDefault();if(e.repeat||s.key||s.pointer!==null)return;s.key=e.code;if(s.paused||['caught','escaped'].includes(s.state.phase))click(s);else press(s);});listen(s,doc,'keyup',e=>{if(live!==s||s.key!==e.code)return;e.preventDefault();s.key=null;release(s);});listen(s,win,'blur',()=>pause(s));listen(s,doc,'visibilitychange',()=>{if(doc.hidden)pause(s);});listen(s,win,'resize',()=>{clear(s);if(s.state.phase==='charging')pause(s);s.fit=null;});render(s);$('[data-fishing-court]').focus?.({preventScroll:true});return true;
  }catch(error){if(live===s&&s)close(s);else root.remove();ui.toast('낚싯대를 준비하지 못했어요. 다시 열어 주세요');return false;}
 }
 return {open,cancel:()=>close(),close:()=>close(),pause,get active(){return !!live;},get camera(){return live?.view.camera;},snapshot:()=>live?{...live.state,paused:live.paused,holding:live.hold,saved:live.saved}:null,tick(dt){const s=live;if(!s||s.paused||doc.hidden)return;if(!canSave()){clear(s);render(s);return;}s.state=stepFishing(s.state,{type:'TICK',dt,hold:s.hold});if(s.state.phase==='caught'&&!s.attempted)saveCatch(s);render(s);},viewport(width,height){if(!live)return {x:0,y:0,width,height};const b=live.root.querySelector('[data-fishing-court]').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,b.left-base.left),y=Math.max(0,b.top-base.top),r={x,y,width:Math.max(1,Math.min(b.width,width-x)),height:Math.max(1,Math.min(b.height,height-y))},key=JSON.stringify(r);if(key!==live.fit){live.fit=key;live.view.fit(r.width,r.height);}return r;}};
}
